<body>
<header class="topbar">
  <div class="header-inner">
    <div class="brand">Booking.com</div>
    <div class="account">
      <span class="currency">USD</span>
      <img class="flag-small" src="__PLACEHOLDER_ASSETS_BASE_DIR__/011.png" width="20" height="20" alt="United States">
      <span class="help btn">?</span>
      <button class="btn">Register</button>
      <button class="btn">Sign in</button>
    </div>
    <nav class="nav">
      <div class="nav-item btn"><span class="nav-icon">▤</span>Stays</div>
      <div class="nav-item btn"><span class="nav-icon">✈</span>Flights</div>
      <div class="nav-item btn"><span class="nav-icon">♧</span>Flight + Hotel</div>
      <div class="nav-item btn"><span class="nav-icon">▰</span>Car rental</div>
      <div class="nav-item btn"><span class="nav-icon">♜</span>Cruises</div>
      <div class="nav-item active btn"><span class="nav-icon">⚙</span>Activities</div>
      <div class="nav-item btn"><span class="nav-icon">▱</span>Airport taxis</div>
    </nav>
  </div>
</header>

<main class="main">
  <section class="content">
    <div class="back btn"><span class="back-arrow">‹</span><span>Ticket options</span></div>
    <div class="step">Step 1 of 2</div>
    <h1>General Admission to Universal Studios Hollywood</h1>
    <div class="warning"><span class="warning-icon">!</span><span>Your selected date is unavailable – choose another</span></div>
    <div class="hosted">This experience is hosted by a <a class="btn" href="#">business</a></div>

    <h2>Your details</h2>
    <div class="signin btn"><span class="person"></span><span>Sign in to use your saved details</span></div>

    <form class="form" autocomplete="off">
      <div class="row">
        <div class="field half" id="firstField">
          <label for="first">First Name <span class="req">*</span></label>
          <input id="first" class="btn" type="text">
        </div>
        <div class="field half" id="lastField">
          <label for="last">Last name <span class="req">*</span></label>
          <input id="last" class="btn" type="text">
        </div>
      </div>

      <div class="field full" id="emailField">
        <label for="email">Email Address <span class="req">*</span></label>
        <input id="email" class="btn" type="text">
        <div id="emailHelper" class="helper" style="display:none"></div>
      </div>

      <div class="field full">
        <label class="phone-label" for="phone">Phone (mobile number preferred) <span class="req">*</span></label>
        <div class="phone-row">
          <select class="country btn" aria-label="Country">
            <option>🇺🇸</option>
          </select>
          <div style="position:relative">
            <span class="prefix">+1</span>
            <input id="phone" class="phone-input btn" type="text">
          </div>
        </div>
      </div>

      <div class="reservation">
        <h2>Reservation details</h2>
        <div class="spinner"></div>
      </div>

      <div class="legal">
        <p>By clicking 'Next: Payment details' and completing a booking, you agree with the <a class="btn" href="#">terms and conditions</a> of Booking.com and the privacy policy of Musement.</p>
        <p>Please see our Privacy Statement to understand how we use and protect your personal information.<br><a class="btn" href="#">Privacy Statement</a></p>
      </div>
    </form>
  </section>
  <aside class="skeletons">
    <div class="skel"></div>
    <div class="skel"></div>
  </aside>
</main>

<script>
  const first=document.getElementById('first');
  const last=document.getElementById('last');
  const email=document.getElementById('email');
  const phone=document.getElementById('phone');
  const firstField=document.getElementById('firstField');
  const lastField=document.getElementById('lastField');
  const emailField=document.getElementById('emailField');
  const helper=document.getElementById('emailHelper');

  function validMark(input, box){
    if(input.value.trim()) box.classList.add('valid');
    else box.classList.remove('valid');
  }
  first.addEventListener('blur',()=>validMark(first,firstField));
  last.addEventListener('blur',()=>validMark(last,lastField));
  first.addEventListener('input',()=>{if(firstField.classList.contains('valid')) validMark(first,firstField)});
  last.addEventListener('input',()=>{if(lastField.classList.contains('valid')) validMark(last,lastField)});

  email.addEventListener('input',()=>{
    emailField.classList.remove('email-error');
    if(email.value.trim()){
      helper.style.display='block';
      helper.className='helper';
      helper.textContent="We'll send your confirmation details to " + email.value.trim();
    }else helper.style.display='none';
  });
  email.addEventListener('blur',()=>{
    if(email.value.trim() && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.value.trim())){
      emailField.classList.add('email-error');
      helper.style.display='block';
      helper.className='helper error';
      helper.textContent='Enter a valid email address';
    }
  });
</script>
</body>
</html>
